 private Button button(LinearLayout parent,String text,String tag,Runnable run){Button b=new Button(getContext());b.setText(text);b.setTag(tag);b.setTextSize(12);b.setAllCaps(false);parent.addView(b,new LayoutParams(parent.getOrientation()==HORIZONTAL?0:-1,-2,parent.getOrientation()==HORIZONTAL?1:0));b.setOnClickListener(v->{if((tag.equals("companySave")||tag.equals("companyDiscard"))&&(!isShown()||getWindowVisibility()!=VISIBLE||!hasWindowFocus()||!isEnabled()||!b.isShown()||!b.isEnabled()))return;run.run();});return b;}
