 private String topic(){int at=topics.getSelectedItemPosition();return at>=0&&at<topicIds.size()?topicIds.get(at):"";}
 void setTopic(String id){restoring=true;reload();int at=topicIds.indexOf(id);if(at>=0)topics.setSelection(at);restoring=false;reload();if(at>=0&&topicChanged!=null)topicChanged.accept(id);}
 void openGraphRelation(String topic,String id){setTopic(topic);restoring=true;stage.setSelection(0);status.setSelection(0);search.setText("");restoring=false;reload();select(id);viewMode=1;views();}
 void reload(){try{String keep=topic(),keepDoc=docIds.isEmpty()?"":docIds.get(Math.max(0,identityDoc.getSelectedItemPosition()));restoring=true;topicIds.clear();List<String> names=new ArrayList<>();JSONArray all=store.read("topics");for(int i=0;i<all.length();i++){JSONObject t=all.getJSONObject(i);topicIds.add(t.getString("id"));names.add(t.optString("name"));}choices(topics,names.toArray(new String[0]));topics.setSelection(Math.max(0,topicIds.indexOf(keep)));docIds.clear();names.clear();all=store.read("docs");for(int i=0;i<all.length();i++){JSONObject d=all.getJSONObject(i);docIds.add(d.getString("id"));names.add(d.optString("title"));}choices(identityDoc,names.toArray(new String[0]));identityDoc.setSelection(Math.max(0,docIds.indexOf(keepDoc)));JSONObject projected=ResearchCompanies.project(topic(),store.read("relations"),store.read("docs"),store.read("reports"));rows=projected.getJSONArray("rows");lastTopic=topic();restoring=false;render();state.setText("当前主题 "+rows.length()+" 条关系；旧核验不升级。\n"+projected.getJSONArray("warnings").toString());}catch(Exception e){restoring=false;state.setText(e.getMessage());}}
 private void views(){if(content==null)return;boolean reading=shortControls&&viewMode==2;headingRow.setVisibility(reading?GONE:VISIBLE);search.setVisibility(reading?GONE:VISIBLE);state.setVisibility(VISIBLE);content.setOrientation(wide?HORIZONTAL:VERTICAL);boolean graphVisible=viewMode==1;list.setVisibility(wide?!graphVisible?VISIBLE:GONE:viewMode==0?VISIBLE:GONE);graphScroll.setVisibility(graphVisible?VISIBLE:GONE);detailScroll.setVisibility(wide||viewMode==2?VISIBLE:GONE);for(View v:new View[]{list,graphScroll,detailScroll})v.setLayoutParams(wide?new LayoutParams(0,-1,v==detailScroll?3:2):new LayoutParams(-1,0,1));}
