 protected void onSizeChanged(int w,int h,int oldw,int oldh){super.onSizeChanged(w,h,oldw,oldh);post(()->{
  // Reparenting controls during layout leaves the weighted reader with stale zero height.
  if(!isAttachedToWindow()||getWidth()<=0||getHeight()<=0)return;
  float density=getResources().getDisplayMetrics().density;boolean nextWide=getWidth()/density>=900,nextShort=getHeight()/density<500;
  if(wide==nextWide&&shortControls==nextShort)return;wide=nextWide;compactHeight(nextShort);views();
 });}
 private void move(View view,LinearLayout parent,int index,LayoutParams params){if(view.getParent() instanceof ViewGroup)((ViewGroup)view.getParent()).removeView(view);parent.addView(view,index,params);}
 private void compactHeight(boolean shortHeight){if(headingRow==null||shortHeight==shortControls)return;shortControls=shortHeight;if(shortHeight){move(stage,headingRow,1,new LayoutParams(0,-2,1));move(status,headingRow,2,new LayoutParams(0,-2,1));filterRow.setVisibility(GONE);move(search,modeRow,0,new LayoutParams(0,-2,2));state.setMaxLines(Integer.MAX_VALUE);move(state,(LinearLayout)detailScroll.getChildAt(0),0,new LayoutParams(-1,-2));}else{move(stage,filterRow,0,new LayoutParams(0,-2,1));move(status,filterRow,1,new LayoutParams(0,-2,1));filterRow.setVisibility(VISIBLE);move(search,this,2,new LayoutParams(-1,-2));move(state,this,getChildCount(),new LayoutParams(-1,-2));state.setMaxLines(2);}}
 private void render(){try{String keep=selected.optString("key"),needle=search.getText().toString().trim().toLowerCase(Locale.ROOT);visible=new JSONArray();adapter.clear();for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);if(stage.getSelectedItemPosition()>0&&!ResearchCompanies.STAGES[stage.getSelectedItemPosition()-1].equals(r.optString("stage")))continue;String s=r.optString("status");int wanted=status.getSelectedItemPosition();if(wanted==1&&(s.equals("manuallyVerified")||s.equals("disputed"))||wanted==2&&!s.equals("manuallyVerified")||wanted==3&&!s.equals("disputed"))continue;JSONObject c=r.optJSONObject("company");String code=c==null?"":c.optString("stockCode");if(!(r.optString("companyName")+r.optString("product")+r.optString("instrumentId")+code).toLowerCase(Locale.ROOT).contains(needle))continue;visible.put(r);adapter.add(r.optString("companyName")+" · "+r.optString("product")+"\n"+ResearchCompanies.stageLabel(r.optString("stage"))+" · "+ResearchCompanies.statusLabel(s)+"\n"+(r.optString("instrumentId").isEmpty()?code.isEmpty()?"未绑定证券":"旧代码 "+code+"（市场未绑定）":r.optString("instrumentId")));}adapter.notifyDataSetChanged();graph.setRows(visible);boolean retained=false;for(int i=0;i<visible.length();i++)if(keep.equals(visible.getJSONObject(i).optString("key")))retained=true;if(retained)select(keep);else{filling=true;selected=new JSONObject();reader.setText("");name.setText("");product.setText("");instrument.setText("");identityQuote.setText("");save.setEnabled(false);filling=false;}views();colors(this);}catch(Exception e){state.setText(e.getMessage());}}
 private void select(String key){try{for(int i=0;i<visible.length();i++){JSONObject r=visible.getJSONObject(i);if(!key.equals(r.optString("key")))continue;filling=true;selected=r;JSONObject original=r.getJSONObject("originalRecord"),d=r.getJSONObject("originalDocument"),c=original.optJSONObject("company");if(c==null)c=new JSONObject();reader.setText("状态："+ResearchCompanies.statusLabel(r.optString("status"))+"\n核验字段："+original.optString("verification")+" / 旧状态："+original.optString("status")+"\n原文完整性："+(r.optBoolean("bodyAvailable")?"当前引用逐字匹配":"仅归档引用 / 当前全文不可得，未复核")+"\n关系："+original.optString("claim")+"\n引用："+original.optString("quote")+"\n证据引用："+(original.optJSONArray("evidenceRefs")==null?"未记录":original.optJSONArray("evidenceRefs").toString())+"\n资料："+d.optString("title")+"\n来源："+d.optString("sourceUrl")+"\n\n"+d.optString("text"));name.setText(c.optString("name"));product.setText(original.optString("product"));instrument.setText(c.optString("instrumentId"));identityQuote.setText(c.optString("identityQuote"));if(docIds.contains(c.optString("identityDocumentId")))identityDoc.setSelection(docIds.indexOf(c.optString("identityDocumentId")));boolean editable=!r.optBoolean("readOnly");for(View v:new View[]{name,product,instrument,identityQuote,identityDoc,save})v.setEnabled(editable);JSONObject draft=drafts.optJSONObject(key);if(editable&&draft!=null){name.setText(draft.optString("name"));product.setText(draft.optString("product"));instrument.setText(draft.optString("instrument"));identityQuote.setText(draft.optString("quote"));if(docIds.contains(draft.optString("documentId")))identityDoc.setSelection(docIds.indexOf(draft.optString("documentId")));}filling=false;graph.setSelected(key);list.setSelection(i);return;}}catch(Exception e){state.setText(e.getMessage());}}
 private void saveCompany(){try{ResearchCompanies.need(selected.length()>0&&!selected.optBoolean("readOnly"),"选择当前原生关系；旧版本只读");JSONObject draft=drafts.optJSONObject(selected.optString("key"));JSONObject original=draft==null?selected.getJSONObject("originalRecord"):draft.getJSONObject("baseline"),latest=null;JSONArray all=store.read("relations");for(int i=0;i<all.length();i++)if(original.optString("id").equals(all.getJSONObject(i).optString("id")))latest=all.getJSONObject(i);ResearchCompanies.need(latest!=null&&latest.toString().equals(original.toString()),"关系已变化，请重读，未覆盖其他修改");latest.put("product",product.getText().toString().trim());if(name.getText().toString().trim().isEmpty()){ResearchCompanies.need(instrument.getText().toString().trim().isEmpty(),"先填公司名或清除身份");latest.remove("company");}else latest.put("company",new JSONObject().put("name",name.getText().toString().trim()).put("instrumentId",instrument.getText().toString().trim()).put("identityDocumentId",docIds.isEmpty()?"":docIds.get(Math.max(0,identityDoc.getSelectedItemPosition()))).put("identityQuote",identityQuote.getText().toString().trim()));store.save("relations",latest);drafts.remove(selected.optString("key"));reload();state.setText("公司/产品已保存，原关系/引文/人工核验保持；没有改自选或账户。");}catch(Exception e){state.setText(e.getMessage());}}
 JSONObject saveState()throws JSONException{return new JSONObject().put("schema","research-company-drafts/v1").put("drafts",new JSONObject(drafts.toString())).put("topic",topic()).put("selected",selected.optString("key")).put("stage",stage.getSelectedItemPosition()).put("status",status.getSelectedItemPosition()).put("search",search.getText().toString()).put("graph",showGraph).put("viewMode",viewMode).put("name",name.getText().toString()).put("product",product.getText().toString()).put("instrument",instrument.getText().toString()).put("quote",identityQuote.getText().toString());}
 void captureDraft(){if(filling||restoring||selected.length()==0||selected.optBoolean("readOnly"))return;try{String key=selected.optString("key");JSONObject old=drafts.optJSONObject(key);drafts.put(key,new JSONObject().put("name",name.getText().toString()).put("product",product.getText().toString()).put("instrument",instrument.getText().toString()).put("quote",identityQuote.getText().toString()).put("documentId",docIds.isEmpty()?"":docIds.get(Math.max(0,identityDoc.getSelectedItemPosition()))).put("baseline",old==null?new JSONObject(selected.getJSONObject("originalRecord").toString()):old.getJSONObject("baseline")));state.setText("本关系有未保存草稿；筛选/重读不覆盖，保存或显式放弃。");}catch(Exception e){state.setText(e.getMessage());}}
 void restoreState(JSONObject s){try{if(!"research-company-drafts/v1".equals(s.optString("schema"))||s.optJSONObject("drafts")==null)throw new IllegalArgumentException("草稿格式无效");restoring=true;filling=true;drafts=new JSONObject(s.getJSONObject("drafts").toString());setTopic(s.optString("topic"));restoring=true;stage.setSelection(Math.max(0,Math.min(6,s.optInt("stage"))));status.setSelection(Math.max(0,Math.min(3,s.optInt("status"))));search.setText(s.optString("search"));showGraph=s.optBoolean("graph");viewMode=Math.max(0,Math.min(2,s.optInt("viewMode",showGraph?1:0)));restoring=false;render();select(s.optString("selected"));filling=false;views();}catch(Exception e){restoring=false;filling=false;state.setText(e.getMessage());}}
